<script setup lang="ts">import { onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { ElMessage } from 'element-plus';import { CopyDocument,Download,Printer } from '@element-plus/icons-vue';import { apiError,diagnosticApi } from '../api';import type { ServiceReport } from '../types';const route=useRoute(),report=ref<ServiceReport|null>(null),loading=ref(true),pdfLoading=ref(false);onMounted(async()=>{try{report.value=await diagnosticApi.report(String(route.params.id))}catch(e){ElMessage.error(apiError(e,'报告尚未生成'))}finally{loading.value=false}});async function copy(){if(!report.value)return;await navigator.clipboard.writeText(report.value.content);ElMessage.success('报告内容已复制')}function printReport(){globalThis.print()}async function downloadPdf(){if(!report.value)return;pdfLoading.value=true;try{const meta=await diagnosticApi.createPdfReport(String(route.params.id));const blob=await diagnosticApi.downloadPdfReport(String(route.params.id));const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=meta.filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);ElMessage.success('PDF 售后报告已下载')}catch(e){ElMessage.error(apiError(e,'PDF 生成或下载失败'))}finally{pdfLoading.value=false}}</script>
<template><div class="page report-page" v-loading="loading"><div class="page-head"><div><p class="eyebrow">SERVICE HANDOFF</p><h1>售后诊断报告</h1><p>将已完成的安全排查过程整理为可交付的文字材料。</p></div><div v-if="report"><el-button :icon="CopyDocument" @click="copy">复制内容</el-button><el-button :icon="Printer" @click="printReport">浏览器打印</el-button><el-button class="brand-button" type="primary" :icon="Download" :loading="pdfLoading" @click="downloadPdf">下载正式 PDF</el-button></div></div><article v-if="report" class="paper"><header><div class="paper-brand"><span>R</span><div><b>RobotCare AI</b><small>第三方安全排障助手</small></div></div><div class="number"><small>报告编号</small><b>{{report.report_number}}</b></div></header><div class="report-meta"><span><small>诊断会话</small>#{{report.session_id}}</span><span><small>生成时间</small>{{report.created_at?.replace('T',' ').slice(0,19)}}</span><span><small>报告状态</small>已生成</span></div><pre>{{report.content}}</pre><footer><b>重要声明</b><p>本报告由独立第三方辅助工具根据用户反馈自动整理，不代表海尔官方诊断结论。涉及拆机、电池、电路、冒烟、异味、漏液或异常高温时，请停止操作并联系官方售后。</p></footer></article><div v-else-if="!loading" class="panel empty">没有找到该诊断报告，请先完成全部安全排查步骤。</div></div></template>
<style scoped>.report-page{max-width:1100px}.paper{background:white;border:1px solid var(--line);box-shadow:0 12px 40px rgba(31,57,48,.08);padding:45px 55px;margin-bottom:50px}.paper header{display:flex;justify-content:space-between;align-items:center;padding-bottom:27px;border-bottom:2px solid #183e32}.paper-brand{display:flex;gap:11px;align-items:center}.paper-brand>span{width:40px;height:40px;border-radius:10px;background:var(--brand);color:#fff;display:grid;place-items:center;font-size:20px;font-weight:800}.paper-brand b,.paper-brand small,.number b,.number small{display:block}.paper-brand small,.number small{color:var(--muted);font-size:10px;margin-bottom:5px}.number{text-align:right}.report-meta{display:grid;grid-template-columns:repeat(3,1fr);background:#f4f8f6;padding:18px 22px;margin:25px 0}.report-meta span{font-size:13px}.report-meta small{display:block;color:var(--muted);font-size:10px;margin-bottom:5px}.paper pre{font:14px/2 "Microsoft YaHei",sans-serif;white-space:pre-wrap;min-height:320px;color:#263a33}.paper footer{border-top:1px solid var(--line);padding-top:22px;color:#7b5a2e}.paper footer b{font-size:12px}.paper footer p{font-size:11px;line-height:1.8}.window{display:none}@media print{.report-page>.page-head{display:none}.report-page{padding:0}.paper{box-shadow:none;border:0;margin:0}.paper footer{break-inside:avoid}}</style>
